import { _decorator, Animation, color, Component, EventTouch, instantiate, Layers, Material, Node, Size, sp, Sprite, SpriteFrame, Tween, tween, UIRenderer, UITransform, v3, Vec3 } from 'cc';
import { PoolMember } from '../Pool/PoolMember';
import { room } from './Room';
import Ulis from '../Misc/Ulis';
import { ui } from '../Manager/UI';
import { sm } from '../Manager/SoundManager';
import { ipm } from '../Manager/InputManager';
import { Slot } from './Slot';
import { NodeOrder } from './MatchAsset/NodeOrder';
const { ccclass, property, executeInEditMode } = _decorator;

@ccclass('Thing')
// @executeInEditMode(true)
export class Thing extends PoolMember {

    @property
    firstIndex: number = -1;
    
    make() { 
        try {

            if(this.node.children[0].getComponent(Sprite)) {
                this.node.children[0].name = "SpBg" + this.node.name;
                this.node.children[1].name = "SpRender" + this.node.name;   
                this.node.children[0].active = true;
                this.node.children[0].getComponent(UIRenderer).color = color(255, 255, 255, 255);
                this.node.children[1].active = true;
            } else {
                this.node.children[0].name = "SpineBg" + this.node.name;
                this.node.children[0].active = true;
                this.node.children[0].getComponent(UIRenderer).color = color(255, 255, 255, 255);

                if(!this.node.children[1]) {                    
                    let ins = instantiate(this.node.children[0]);
                    ins.parent = this.node;
                }
                this.node.children[1].name = "SpineRender" + this.node.name;  
                this.node.children[1].active = true;

                if(!this.node.children[2]) {                    
                    let ins = instantiate(this.node);
                    ins.parent = this.node;
                    ins.destroyAllChildren();
                    ins.position = v3(0, 0, 0);
                    ins.getComponent(Thing)?.destroy();      
                    this.node.getComponent(Sprite)?.destroy();  
                }

                this.node.children[2].active = false;
            }
      
        } catch (error) {
            
        }
        if(this.node.children.length > 0) {
            this.node.children.forEach(c => {
                c.getComponent(Thing)?.destroy();
                c.getComponent(Animation)?.destroy();
                c.getComponent(NodeOrder)?.destroy();
            })
            return;
        }
        let ins = instantiate(this.node);
        ins.parent = this.node;
        ins.position = v3(0, 0, 0);
        ins.getComponent(Thing)?.destroy();        
        this.node.children[0].getComponent(Animation)?.destroy();
        this.node.children[0].getComponent(NodeOrder)?.destroy();
        this.node.getComponent(Sprite)?.destroy();
        
        let ins2 = instantiate(this.node.children[0]);
        ins2.parent = this.node;
        ins2.position = v3(0, 0, 0);
        ins2.getComponent(Thing)?.destroy();        
        this.node.children[1].getComponent(Animation)?.destroy();
        this.node.children[1].getComponent(NodeOrder)?.destroy();
        this.node.children[0].name = "SpBg" + this.node.name;
        this.node.children[1].name = "SpRender" + this.node.name;
        let uit = this.node.children[0].getComponent(UITransform);
        uit.width *= 1.1;
        uit.height *= 1.1;        
    }

    _inited: boolean = false

    @property
    set inited(value: boolean) { 
        this._inited = false; 
        this.make();
    }

    get inited() { 
        return this._inited; 
    }

    @property
    thingType: number = -1;
    sprite: UIRenderer = null;
    frame: SpriteFrame = null;
    bg: UIRenderer = null;
    material: Material = null;
    hightlighted: boolean = false
    sizeTween: Tween<any> = null;
    comps: UITransform[] = [];
    sizes: Vec3[] = [];
    box: Slot = null;
    slot: Slot = null;

    init() {
        this.comps = this.getComponentsInChildren(UITransform).filter(c => c.node !== this.node);
        
        this.sizes = this.comps.map(c => c.node.scale.clone());
        this.bg = this.node.getComponentsInChildren(UIRenderer)[0];   
        this.bg.color = color(255, 255, 255, 0);
        this.sprite = this.node.getComponentsInChildren(UIRenderer)[1];   
        this.sprite.color = color(255, 255, 255, 255); 
        this.bg.node.active = true;
        this.sprite.node.active = true;
        this.onTouch();
        this.material = this.sprite.material;  
        this.frame = this.getComponentInChildren(Sprite)?.spriteFrame;
    }

    flicker() {
        this.onHightlight();
        this.scaleSize();
    } 
    onHightlight() { 
        this.bg.color = color(255, 255, 255, 255);
        this.sizeTween?.stop();
        // this.material.setProperty("useOutline", 1);
        // this.material.setProperty("alpha", 1);
        // this.material.setProperty("useOutline", 1, 1);
        // this.material.setProperty("alpha", 1, 1);
        // if(this.spine) {
        //     this.spine.customMaterial = this.material;
        // } else {
        //     this.sprite.material = this.material;
        // }
        this.hightlighted = true;
    }

    offAnim() {
        this.getComponentsInChildren(sp.Skeleton).forEach(s => {
            // s.setAnimation(0, "Idle", false) 
            s.timeScale = 0;
        });
    }



    offHightlight() { 
        // this.bg.color = color(255, 255, 255, 0);
        this.sizeTween?.stop();
        // this.material.setProperty("useOutline", 0);
        // this.material.setProperty("useOutline", 0, 1);
        // if(this.spine) {
        //     this.spine.customMaterial = this.material;
        // } else {
        //     this.sprite.material = this.material;
        // }
        this.comps.forEach((c, i) => {
            c.node.scale = this.sizes[i];
        })
        this.hightlighted = false;
    }

    offFlicker() { 
        this.bg.color = color(255, 255, 255, 0);
        this.sizeTween?.stop();
        this.comps.forEach((c, i) => {
            c.node.scale = this.sizes[i];
        })
        this.hightlighted = false;
    }

    scaleSize(loop: boolean = true) {
        const t = this;
        let mul = loop ? 1 : 0.5;
        this.sizeTween?.stop();
        this.sizeTween = tween({})
        .to(0.5 * mul, {}, {
            onUpdate(target, ratio) {
                t.comps.forEach((c, i) => {
                    let s = t.sizes[i].clone();
                    s.x *= 1 + 0.1 * ratio;
                    s.y *= 1 + 0.1 * ratio;
                    c.node.scale = s;
                })
            },
        })
        .to(0.5 * mul, {}, {
            onUpdate(target, ratio) {
                t.comps.forEach((c, i) => {
                    let s = t.sizes[i].clone();
                    s.x *= 1.1 - 0.1 * ratio;
                    s.y *= 1.1 - 0.1 * ratio;
                    c.node.scale = s;
                })
            },
        })
        .call(() => {
            if(loop)
            this.scaleSize();
        })
        .start();
    }


    offTouch() {
        this.node.off(Node.EventType.TOUCH_START, this.onTouchStart, this);
        this.node.off(Node.EventType.TOUCH_MOVE, this.none, this);
        this.node.off(Node.EventType.TOUCH_END, this.none, this);
        this.node.off(Node.EventType.TOUCH_CANCEL, this.none, this);
    }

    onTouch() {
        this.node.on(Node.EventType.TOUCH_START, this.onTouchStart, this);
        this.node.on(Node.EventType.TOUCH_MOVE, this.none, this);
        this.node.on(Node.EventType.TOUCH_END, this.none, this);
        this.node.on(Node.EventType.TOUCH_CANCEL, this.none, this);
    }

    none() {}

    off() {
        this.offTouch();
        this.sprite.enabled = true;
    }

    onDespawn() {
        this.node.destroy(); 
    }

    onTouchStart(event: EventTouch) {
        if(this.firstIndex == -1) {
            ipm.fisrtTap();
        }
        let pos = event.getLocation();
        let wpos = ui.uiCam.screenToWorld(v3(pos.x, pos.y, 0));
        
        room.checkBox(this, wpos);
        // let rs = ui.checkNodeInsideScreen(this.node, 100);
        // console.log(rs);
        
    }

    
    setUpLayer() {
        let l = Layers.nameToLayer("Particle");
        Ulis.allNode(this.node, (node) => node.layer = Math.pow(2, l));
    }

    setDownLayer() {
        let l = Layers.nameToLayer("UI_2D");
        Ulis.allNode(this.node, (node) => node.layer = Math.pow(2, l));
    }

    update(deltaTime: number) {
        
    }
}


